        super().__init__(config)


class LightOnOCRVisionRotaryEmbedding(PixtralRotaryEmbedding):
    def __init__(self, config: LightOnOCRVisionConfig, device=None, layer_type=None):
        super().__init__(config, device, layer_type)

    @staticmethod
    def compute_default_rope_parameters(
        config: Optional[LightOnOCRVisionConfig] = None,
        device: Optional["torch.device"] = None,
        seq_len: Optional[int] = None,
    ) -> tuple["torch.Tensor", float]:
        base = config.rope_parameters["rope_theta"]
        dim = getattr(config, "head_dim", None) or config.hidden_size // config.num_attention_heads

        attention_factor = 1.0

        max_patches_per_side = config.image_size // config.patch_size
        h = torch.arange(max_patches_per_side)
        w = torch.arange(max_patches_per_side)

        freqs = 1.0 / (base ** (torch.arange(0, dim, 2).float() / dim))
        freqs_h = torch.outer(h, freqs[::2]).float()
        freqs_w = torch.outer(w, freqs[1::2]).float()
        inv_freq = torch.cat(
            [
                freqs_h[:, None, :].repeat(1, max_patches_per_side, 1),
                freqs_w[None, :, :].repeat(max_patches_per_side, 1, 1),
            ],
            dim=-1,
        ).reshape(-1, dim // 2)
        inv_freq = torch.cat((inv_freq, inv_freq), dim=-1)
        return inv_freq, attention_factor


class LightOnOCRVisionAttention(PixtralAttention):
    def __init__(self, config: LightOnOCRVisionConfig):
        super().__init__(config)
        self.num_key_value_groups = 1


class LightOnOCRVisionAttentionLayer(PixtralAttentionLayer):
    def __init__(self, config: LightOnOCRVisionConfig):
        super().__init__(config)


class LightOnOCRVisionTransformer(PixtralTransformer):
    def __init__(self, config: LightOnOCRVisionConfig):
